def expected(payload):
    user_id = payload.get("user_id")
    orders = payload.get("orders")
    if user_id is None or orders is None:
        return None  # error-contract input (user not found) — handled by error_contract

    total_spend = 0.0
    for order in orders:
        if order.get("status") == "COMPLETED":
            total_spend += order.get("amount", 0.0)
    total_spend = round(total_spend, 2)

    if total_spend < 5000:
        tier, cashback, next_tier, next_lower = "Bronze", 0, "Silver", 5000
    elif total_spend < 20000:
        tier, cashback, next_tier, next_lower = "Silver", 1, "Gold", 20000
    elif total_spend < 50000:
        tier, cashback, next_tier, next_lower = "Gold", 2, "Platinum", 50000
    else:
        tier, cashback, next_tier, next_lower = "Platinum", 5, None, None

    if next_tier is None:
        spend_to_next = 0.0
    else:
        spend_to_next = round(next_lower - total_spend, 2)

    return {
        "user_id": user_id,
        "total_spend": total_spend,
        "tier": tier,
        "cashback_percent": cashback,
        "next_tier": next_tier,
        "spend_to_next_tier": spend_to_next
    }
